//! wgpu backend/device lifecycle, residency and budgets; GPU API types hidden from
//! document/contracts.
//!
//! Implements the pigment-owned `RenderBackend` port (`hsk_studio_pigment::render_plan`) as
//! [`GpuBackend`]. The plan IR, `StudioBlendMode`, the receipt and the reference blend arithmetic
//! (`hsk_studio_pigment::blend_math`) live in pigment (CX-CAP-001); this crate adds headless
//! device acquisition, generation/loss handling, byte-accounted residency and the WGSL compute
//! pass. No wgpu type appears in any public signature (STU-ARC-002); a missing adapter is the
//! typed `Unavailable`, never a silent CPU fallback.
#![forbid(unsafe_code)]
pub mod device;
pub mod error;
mod kernel;
pub mod plan_sink;
pub mod report;
pub mod residency;

pub use device::{AdapterKind, BackendChoice, DeviceInfo, DeviceOptions, GpuContext};
pub use error::{GpuError, Reason};
pub use kernel::{gpu_blend_qualifies, gpu_blend_supported};
pub use plan_sink::{GpuBackend, GpuStats, RENDERER_NAME, RENDERER_VERSION};
pub use report::{outcome_of, report};
pub use residency::{Reservation, ReservationId, Residency, ResidentKey};

pub const DESCRIPTOR: &str = r#"{"module":"STUDIO-MODULE-RENDER_GPU","version":1,"renderer":"hsk-studio-render-gpu/0.1","operation":"execute_render_plan_to_tile_sink","api":"impl RenderBackend<NoVector> for GpuBackend (pigment render_plan port); GpuBackend::new(DeviceOptions) never fails and holds Ready|Lost|Unavailable|Failed (failure() = the typed pipeline failure of a present adapter); execute_detailed returns (RenderReceipt, GpuStats); reacquire(cancel) is the only recovery; report(result, correlation, revision, cancel, observe, sink) emits one terminal Observe frame","command":"render-gpu-consumer --descriptor | --probe | --selftest","device":{"acquire":"headless: wgpu instance + adapter + device with no surface, no window, no focus; downlevel limits; validation layers off","backends":"auto (one backend per instance in platform order: windows dx12 then vulkan, apple metal, else vulkan)|vulkan|dx12|metal|none (none = forced Unavailable(no_adapter))","generation":"u64, 1 on first acquire, +1 on every reacquire; a lost device latches DeviceLost{generation} for every later execute until reacquire","loss":"the wgpu device-lost callback is the only latch; the backend polls the device before every execute and state query, so a destroyed device is detected by that callback; simulate_device_loss = wgpu Device::destroy only, never sets the latch; driver-initiated loss (TDR, adapter removal) not proven","unavailable":"no adapter -> Unavailable(no_adapter) (after admission); adapter without device -> no_device; request timeout -> adapter_timeout; never a CPU fallback","pipeline_failure":"adapter and device present but the WGSL shader or compute pipeline fails validation -> GpuError::Pipeline(shader_validation) in its own Failed state (GpuBackend::failure), at the port Unavailable(shader_validation); never Unavailable(no_adapter|no_device), so a test or probe fails instead of skipping"},"plan":"hsk_studio_pigment::render_plan::RenderPlan; admit() runs first (cancel, stale revision, validation, per-operator class); root group or leaf of solid and tile layers; nested isolated groups (one chunk buffer per nesting level) and pass-through groups; per-layer coverage masks; clip-to-base runs","blend":{"owner":"hsk_studio_pigment::blend_math (reference); WGSL reproduces composite_over in f32","supported":"normal plus every layer-applicable separable mode pigment marks Exact (darken, multiply, colour_burn, lighten, screen, colour_dodge, overlay, soft_light, hard_light, difference, exclusion); the WGSL mode switch is generated from pigment MODES facts (gpu_blend_qualifies) so pigment owns the list, kernel.rs owns only the per-mode formula bodies; a qualifying mode without a body is unsupported","exactness":"fitted (tolerance-equal, not bit-exact: GPU fused multiply-add and division); tile/solid/isolated group/pass-through group/mask exact (structure and f32 bits preserved; mask coverage is converted on the host exactly as render-cpu does); fill_opacity approximate (folded as a product); a leaf root (solid or tile root, no layer) runs one Normal kernel pass over transparent, so the receipt records normal: fitted and an Exact floor refuses it","refused":"approximate and non-separable and tool-only and unspecified modes, vector, pass-through with opacity or fill below 1, non-isolated blended groups, mask density other than 1, mask on a pass-through layer, premultiplied alpha, samples outside [0,1]: Unsupported at admission or source preparation, before any upload"},"clip_to_base":"supports_clip_to_base() = true. Run [base, clipped...] (a clipped layer carries MaskInput::clip_to_base()) is one isolated unit G on its own chunk buffer: G = base content with the base mask (no opacity/fill/mode); each clipped layer composites onto G with its own mode/opacity/fill and source alpha times the base alpha, alpha of G held at the base alpha; G composites onto the parent with the BASE layer mode/opacity/fill. Class Approximate (pigment rule unverified against Photoshop). Base that is a pass-through group is refused","formats":{"colour":"rgb_f32le","alpha":"f32le straight, separate plane","chunk":"tightly packed row-major, sink receives rect + both planes"},"memory":{"residency":"pure-Rust LRU with pins and a hard budget, checked byte arithmetic (no overflow near u64::MAX: evict or BudgetExceeded); every device buffer is charged before it is created and released on every exit; peak and evictions are counted","buffers_per_call":"one chunk destination per group nesting level (1 + isolated depth) + staging (+ src when tiles) (+ f32 mask when masks) + 64 byte params","chunk":"shrinks from 512 until all buffers fit min(request.max_working_bytes, residency budget, device buffer limits); smaller than 64 texels -> BudgetExceeded","units":"RGBA f32 = 16 bytes per texel"},"failure":"cancel/deadline between chunks and layers; stale revision, invalid plan, unsupported operator, unresolved or mismatching source refuse before the first device call; sink error aborts; scratch released on every exit; receipt only after the last chunk","privacy":"no pixel, profile or path bytes in telemetry; adapter name only in the receipt identity text","pending":["non-separable modes (hue, saturation, colour, luminosity) and Approximate separable modes: add a FORMULAS body + parity case each","vector coverage, mask density","content-addressed tile cache across executions (ResidentKey::Tile)","f16/HDR accumulation, multi-GPU, surface presentation (host)","backend-qualified oracle on discrete GPU, Vulkan and Metal: only the backend named in the lane file is proven"]}"#;
